import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CyZTVJbV.js";const g=JSON.parse('{"title":"kiwa v1.43 released — Edge / Serverless 深化 milestone + 縦深化 pair 第 12 新規 base pair 導入","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.43/gh-discussions-announcement.md","filePath":"announcements/v1.43/gh-discussions-announcement.md"}'),d={name:"announcements/v1.43/gh-discussions-announcement.md"};function i(s,e,n,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="kiwa-v1-43-released-—-edge-serverless-深化-milestone-縦深化-pair-第-12-新規-base-pair-導入" tabindex="-1">kiwa v1.43 released — Edge / Serverless 深化 milestone + 縦深化 pair 第 12 新規 base pair 導入 <a class="header-anchor" href="#kiwa-v1-43-released-—-edge-serverless-深化-milestone-縦深化-pair-第-12-新規-base-pair-導入" aria-label="Permalink to &quot;kiwa v1.43 released — Edge / Serverless 深化 milestone + 縦深化 pair 第 12 新規 base pair 導入&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>kiwa v1.43 is out. <strong>The 12th 縦深化 pair is introduced</strong> — Edge / Serverless base at v1.43, the first new pair base since v1.37 Security (5 milestones ago). This matches the 5-milestone new-base cadence established after 3 depth-4 records (v1.40 AI/LLM + v1.41 Payment + v1.42 Observability).</p><h2 id="what-s-new" tabindex="-1">What&#39;s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s new&quot;">​</a></h2><h3 id="kiwa-lab-edge-v1-2-0" tabindex="-1"><code>@kiwa-lab/edge</code> v1.2.0 <a class="header-anchor" href="#kiwa-lab-edge-v1-2-0" aria-label="Permalink to &quot;`@kiwa-lab/edge` v1.2.0&quot;">​</a></h3><p>v1.1.0 → v1.2.0 minor bump. 8 new advanced axes added on top of the existing 8-axis base.</p><ul><li><strong>cold-start</strong> — Serverless function warm/cold path + provisioned concurrency modeling. <code>startColdStartPool</code> + <code>invokeColdStart</code> + <code>preWarmInstance</code> + <code>evictExpired</code>.</li><li><strong>middleware-chain</strong> — Edge middleware pipeline (auth → rewrite → cache → transform + short-circuit). <code>startMiddlewareChain</code> + <code>enterMiddleware</code> + <code>rewriteRequest</code> + <code>shortCircuit</code> + <code>completeMiddleware</code>.</li><li><strong>kv-eventual-consistency</strong> — Read-your-writes + monotonic-reads consistency detection. <code>startKvConsistency</code> + <code>recordWriteQuorum</code> + <code>observeRead</code> + <code>forceConvergence</code>.</li><li><strong>r2-multipart</strong> — Resumable multipart upload with per-part checksum verification. <code>initiateMultipart</code> + <code>uploadPart</code> + <code>verifyChecksum</code> + <code>completeMultipart</code>.</li><li><strong>d1-read-replica</strong> — Primary-replica database routing with lag detection + failover. <code>startD1</code> + <code>writeToPrimary</code> + <code>readFromReplica</code> + <code>reportLag</code>.</li><li><strong>do-state-migration</strong> — DurableObject schema versioning + zero-downtime rollout + rollback. <code>initiateMigration</code> + <code>bumpSchema</code> + <code>migrateInstance</code> + <code>completeRollout</code> + <code>rollbackMigration</code>.</li><li><strong>websocket-hibernation</strong> — Cloudflare Workers / Vercel Edge WebSocket hibernation model. <code>startHibernationSession</code> + <code>hibernate</code> + <code>resume</code> + <code>restoreState</code> + <code>completeReconnect</code>.</li><li><strong>global-routing</strong> — Anycast + geo + latency-based failover routing. <code>startRoutingPool</code> + <code>receiveAnycast</code> + <code>matchGeo</code> + <code>selectByLatency</code> + <code>markUnhealthy</code>.</li></ul><p>3 platform (cloudflare / vercel / deno) × 16 axis (8 v0.2 base + 8 v1.2 advanced) = 48-cell fidelity grid.</p><h3 id="_3-new-dogfood-apps" tabindex="-1">3 new dogfood apps <a class="header-anchor" href="#_3-new-dogfood-apps" aria-label="Permalink to &quot;3 new dogfood apps&quot;">​</a></h3><ul><li><code>examples/dogfood-edge-serverless-cold-start-app</code> — 64 tests. cold / warm / provisioned 3 axis × 3 platform mock/real adapter + fidelity harness.</li><li><code>examples/dogfood-edge-durable-object-migration-app</code> — 60 tests. schema-bump / data-migrate / rollout 3 axis × 3 platform mock/real adapter + fidelity harness.</li><li><code>examples/dogfood-edge-global-routing-app</code> — 60 tests. anycast-routing / geo-matching / replica-affinity 3 axis × 3 platform mock/real adapter + fidelity harness.</li></ul><p>Each dogfood ships with real-driver env-gate (<code>KIWA_MODE=real</code> + <code>EDGE_*_STACK_READY=1</code> + <code>KIWA_EDGE_*_URL</code>) so the fidelity harness can sweep against real Cloudflare Workers + Vercel Edge + AWS Lambda + Deno Deploy backends.</p><h3 id="_3-new-tutorials" tabindex="-1">3 new tutorials <a class="header-anchor" href="#_3-new-tutorials" aria-label="Permalink to &quot;3 new tutorials&quot;">​</a></h3><ul><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/94-serverless-cold-start" target="_blank" rel="noreferrer">Tutorial 94 — Serverless cold-start</a></strong> — cold path + warm pool + provisioned concurrency + latency observability walkthrough.</li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/95-durable-object-migration" target="_blank" rel="noreferrer">Tutorial 95 — DurableObject state migration</a></strong> — schema versioning + data migrate + zero-downtime rollout + rollback walkthrough.</li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/96-global-routing" target="_blank" rel="noreferrer">Tutorial 96 — Global routing</a></strong> — Anycast + geo matching + latency-based failover + D1 read replica affinity walkthrough.</li></ul><h3 id="_21-milestone-consecutive-snippet-validation-streak" tabindex="-1">21-milestone consecutive snippet validation streak <a class="header-anchor" href="#_21-milestone-consecutive-snippet-validation-streak" aria-label="Permalink to &quot;21-milestone consecutive snippet validation streak&quot;">​</a></h3><p>v1.23 → v1.43 = 21 milestones with tutorial code snippet validation tests. Each milestone&#39;s tutorials ship with an in-repo test that executes every code block, so drift between docs and API is caught at merge time.</p><h3 id="縦深化-pair-pattern-grid" tabindex="-1">縦深化 pair pattern grid <a class="header-anchor" href="#縦深化-pair-pattern-grid" aria-label="Permalink to &quot;縦深化 pair pattern grid&quot;">​</a></h3><p>12 pairs now on record.</p><table tabindex="0"><thead><tr><th>Pair #</th><th>Domain</th><th>Path</th><th>Depth</th></tr></thead><tbody><tr><td>1</td><td>Auth</td><td>v1.21→v1.22</td><td>2</td></tr><tr><td>2</td><td>Realtime</td><td>v1.13→v1.28</td><td>2</td></tr><tr><td>3</td><td>Streaming</td><td>v1.20→v1.31</td><td>2</td></tr><tr><td>4</td><td>Database</td><td>v1.14→v1.32</td><td>2</td></tr><tr><td>5</td><td>Payment</td><td>v1.14→v1.19→v1.33→v1.41</td><td>4</td></tr><tr><td>6</td><td>Frontend</td><td>v1.16→v1.34</td><td>2</td></tr><tr><td>7</td><td>Observability</td><td>v1.14→v1.17→v1.35→v1.42</td><td>4</td></tr><tr><td>8</td><td>Search</td><td>v1.14→v1.15→v1.36</td><td>3</td></tr><tr><td>9</td><td>Security</td><td>v1.37→v1.39</td><td>2</td></tr><tr><td>10</td><td>AI/LLM</td><td>v1.12→v1.15→v1.38→v1.40</td><td>4</td></tr><tr><td>11</td><td>Security base</td><td>v1.37</td><td>1 (introduced v1.37)</td></tr><tr><td><strong>12</strong></td><td><strong>Edge / Serverless</strong></td><td><strong>v1.43 (new base)</strong></td><td><strong>1</strong></td></tr></tbody></table><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/edge@^1.2</span></span></code></pre></div><p>Additive-only. No breaking changes.</p><h2 id="migration-guide" tabindex="-1">Migration guide <a class="header-anchor" href="#migration-guide" aria-label="Permalink to &quot;Migration guide&quot;">​</a></h2><p><a href="https://cardene777.github.io/kiwa/migrations/v1.42-to-v1.43" target="_blank" rel="noreferrer">v1.42 → v1.43 migration guide</a></p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>v1.44+ will introduce new pair bases at ~5-milestone cadence. The next expected III depth for Edge / Serverless is around v1.62±, following the 4-段拡張 pattern established by pair 9-11.</p>',25)])])}const u=t(d,[["render",i]]);export{g as __pageData,u as default};
